'use strict';
const $=s=>document.querySelector(s);let bands=[],current=0,filter='all',timer=null,openedAt=0;const key='sound-in-sight-v1';let revealed=new Set;try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved))revealed=new Set(saved.filter(x=>typeof x==='string'))}catch{}
function persist(){try{localStorage.setItem(key,JSON.stringify([...revealed]))}catch{}}
function source(b,full=false){return `assets/${b.id}${full?'-full.webp':'.webp'}`}
function cancelCountdown(){if(timer!==null){clearInterval(timer);timer=null}}
function updateProgress(){const n=bands.filter(b=>revealed.has(b.id)).length;$('#progressText').textContent=`已揭晓 ${n} / ${bands.length}`;$('#progressBar').style.width=`${n/bands.length*100}%`}
function render(){const grid=$('#grid');grid.replaceChildren();const visible=bands.filter(b=>filter==='all'||(filter==='seen'?revealed.has(b.id):!revealed.has(b.id)));for(const b of visible){const seen=revealed.has(b.id),card=document.createElement('button');card.className=`card${seen?' seen':''}`;card.setAttribute('aria-label',seen?`第${b.id}幅：${b.name}，查看作品`:`第${b.id}幅摄影谜面，打开猜名字`);const box=document.createElement('div');box.className='card-image';const img=document.createElement('img');img.src=source(b);img.loading=Number(b.id)>4?'lazy':'eager';img.decoding='async';img.width=640;img.height=960;img.alt=seen?`${b.name}的摄影意象`:`第${b.id}幅摄影谜面`;img.onerror=()=>{img.onerror=null;img.src=`assets/${b.id}.png`};box.append(img);const meta=document.createElement('div');meta.className='card-meta';const num=document.createElement('span');num.className='card-no';num.textContent=b.id+' / 30';const status=document.createElement('span');status.className='card-status';status.textContent=seen?b.name:'名字，等你猜';meta.append(num,status);card.append(box,meta);card.onclick=()=>open(bands.indexOf(b));grid.append(card)}$('#empty').hidden=visible.length>0;updateProgress()}
function open(index){cancelCountdown();current=(index+bands.length)%bands.length;const b=bands[current];$('#viewer').dataset.work=b.id;$('#workNo').textContent=`PHOTOGRAPHIC RIDDLE / NO. ${b.id}`;$('#position').textContent=`${b.id} / 30`;const img=$('#fullImage');$('#retryImage').hidden=true;img.onerror=()=>{$('#retryImage').hidden=false};img.onload=()=>{$('#retryImage').hidden=true};img.alt=revealed.has(b.id)?`${b.name}的摄影意象`:`第${b.id}幅摄影谜面`;img.src=source(b,true);$('#guess').value='';$('#guessFeedback').textContent='';$('#hint').hidden=true;$('#hint').textContent=b.hint;$('#hintBtn').textContent='给我一点线索 ＋';$('#reveal').disabled=false;$('#reveal').innerHTML='揭晓答案 <span>等待 3 秒</span>';$('#countdownNote').textContent='给直觉一点时间。';$('#question').hidden=revealed.has(b.id);$('#answer').hidden=!revealed.has(b.id);if(revealed.has(b.id))fillAnswer();if(!$('#viewer').open)$('#viewer').showModal();$('#viewer').scrollTop=0;document.body.style.overflow='hidden';openedAt=Date.now();const next=bands[(current+1)%bands.length];const preload=new Image;preload.src=source(next);}
function fillAnswer(){const b=bands[current];$('#bandName').textContent=b.name;$('#bandMeta').textContent=`${b.region} · ${b.genre}`;$('#poetic').textContent=b.hint;$('#download').href=`assets/${b.id}.png`;$('#download').download=`听见画面-${b.name}-2x3.png`;$('#fullImage').alt=`${b.name}的摄影意象`;$('#resultLabel').textContent='与这个名字，见面。'}
function reveal(){if(timer!==null||revealed.has(bands[current].id))return;const b=bands[current],stamp=Date.now();$('#reveal').disabled=true;$('#guess').disabled=true;const tick=()=>{const left=Math.max(0,3-Math.floor((Date.now()-stamp)/1000));$('#reveal').textContent=left?`还有 ${left} 秒，与答案见面…`:'揭晓';$('#countdownNote').textContent=left?`${left} 秒后揭晓答案`:'答案已揭晓';if(!left){cancelCountdown();$('#guess').disabled=false;revealed.add(b.id);persist();fillAnswer();$('#question').hidden=true;$('#answer').hidden=false;render()}};tick();timer=setInterval(tick,100)}
const tradMap={'隊':'队','盤':'盘','兩':'两','玫':'玫','橘':'橘','褲':'裤','蝟':'猬','萬':'万','青':'青','條':'条','龜':'龟','馬':'马','龍':'龙','飛':'飞','車':'车','計':'计','劃':'划','東':'东','沒':'没','對':'对','樂':'乐','團':'团','聲':'声','玩':'玩','連':'连','真':'真','迴':'回','霓':'霓','園':'园','丟':'丢','書':'书','級':'级','場':'场','鴨':'鸭','鵝':'鹅','極':'极','麵':'面','針':'针'};
function normalize(v){return v.replace(/[\s·•・\-—_]/g,'').replace(/[\u4e00-\u9fff]/g,c=>tradMap[c]||c).replace(/(乐队|乐团)$/,'').toLowerCase()}
$('#guessForm').onsubmit=e=>{e.preventDefault();if(timer!==null)return;const v=$('#guess').value.trim();if(!v){$('#guessFeedback').textContent='也可以直接点击揭晓，让答案自己出现。';return}const b=bands[current];if([b.name,...b.aliases].some(a=>normalize(a)===normalize(v))){$('#guessFeedback').textContent='你猜中了。3 秒后，与这个名字见面。';reveal()}else{$('#guessFeedback').textContent='还没对上这个名字，再看看画面里的线索。'}};
$('#reveal').onclick=reveal;$('#hintBtn').onclick=()=>{const hidden=$('#hint').hidden;$('#hint').hidden=!hidden;$('#hintBtn').textContent=hidden?'收起线索 −':'给我一点线索 ＋'};
$('#prev').onclick=()=>{$('#guess').disabled=false;open(current-1)};$('#next').onclick=()=>{$('#guess').disabled=false;open(current+1)};
function close(){cancelCountdown();$('#guess').disabled=false;$('#viewer').close();document.body.style.overflow=''}$('#closeViewer').onclick=close;$('#viewer').addEventListener('close',()=>{cancelCountdown();$('#guess').disabled=false;document.body.style.overflow=''});$('#viewer').addEventListener('click',e=>{if(e.target===$('#viewer')){const r=$('#viewer').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});$('#retryImage').onclick=()=>{$('#retryImage').hidden=true;$('#fullImage').src=source(bands[current],true)+'?retry='+Date.now()};
$('#start').onclick=()=>{const i=bands.findIndex(b=>!revealed.has(b.id));open(i<0?0:i)};$('#heroWork').onclick=()=>open(1);$('#random').onclick=()=>{const choices=bands.map((b,i)=>({b,i})).filter(({b})=>!revealed.has(b.id));open(choices.length?choices[Math.floor(Math.random()*choices.length)].i:Math.floor(Math.random()*bands.length))};document.querySelectorAll('[data-filter]').forEach(btn=>btn.onclick=()=>{filter=btn.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===btn);x.setAttribute('aria-pressed',String(x===btn))});render()});
$('#aboutBtn').onclick=()=>{$('#about').showModal();document.body.style.overflow='hidden'};$('#closeAbout').onclick=()=>$('#about').close();$('#about').addEventListener('close',()=>document.body.style.overflow='');$('#reset').onclick=()=>{if(confirm('重新开始？将清除本浏览器里已经揭晓的名字。')){cancelCountdown();revealed.clear();persist();render()}};
document.addEventListener('keydown',e=>{if(!$('#viewer').open||['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='ArrowRight'){$('#guess').disabled=false;open(current+1)}if(e.key==='ArrowLeft'){$('#guess').disabled=false;open(current-1)}});
fetch('data.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(data=>{bands=data;render()}).catch(()=>{$('#grid').textContent='作品集暂时加载失败，请刷新页面重试。';$('#start').disabled=true;$('#random').disabled=true;$('#heroWork').disabled=true});
